import{_ as n,l as s,o as r,c as p,v as i,p as d,x as t,d as l,i as m,S as h,b as e}from"./chunks/framework.InCnrqk-.js";const F=JSON.parse('{"title":"深度缩放初始化","description":"","frontmatter":{"title":"深度缩放初始化","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/depth-scaled-init.md","filePath":"llm/depth-scaled-init.md","lastUpdated":1789023840000}'),u={name:"llm/depth-scaled-init.md"};function L(N,a,c,f,g,x){const o=s("Mermaid");return r(),p("div",null,[a[1]||(a[1]=i('<h1 id="深度缩放初始化" tabindex="-1">深度缩放初始化 <a class="header-anchor" href="#深度缩放初始化" aria-label="Permalink to &quot;深度缩放初始化&quot;">​</a></h1><div class="epigraph"><p>残差把每层增量加进同一条流；层数变多时，若不把残差分支的起步幅度按深度缩小，输出尺度与梯度会先被加法而不是被非线性毁掉。</p><footer>—— Radford et al., GPT-2, 2019；Huang et al., T-Fixup, ICML 2020；Wang et al., DeepNet, 2022</footer></div><p><a href="/llm/xavier-kaiming-init">上一课</a>让单个 GEMM 的前向 / 反向方差守恒。缺口是 <a href="/llm/residual-stream">残差流</a>：\\(x\\leftarrow x+F(x)\\) 在 \\(F\\) 已守恒时仍把 \\(\\mathrm{Var}(F)\\) <strong>加</strong> \\(L\\) 次。GPT-2 把残差投影乘 \\(1/\\sqrt{N}\\)；T-Fixup 与 DeepNet 把这件事写成可训到极深的初始化。本课只补「深度」这一轴，不重写 Xavier 的扇入公式，也不进入 <a href="/llm/pre-ln-post-ln">Pre-LN</a> 的位置之争——位置改变的是哪条路需要缩放，不是要不要缩放。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>设每层 \\(F_\\ell\\) 在初始化时与输入近似无关、方差为 \\(v\\)。则 \\(L\\) 层之后</p> \\[\\mathrm{Var}(x_L)\\approx\\mathrm{Var}(x_0)+L v. \\]<p>\\(v\\) 若按 Xavier 钉在 \\(O(1)\\)，\\(L=96\\) 的流比嵌入大约一个数量级。注意力 logits 随 \\(\\|q\\|\\|k\\|\\) 涨，FFN 的中间激活跟着涨，第一步的梯度裁剪就会常年贴顶。这不是优化器坏了，是<strong>加法深度没有进入初始化</strong>。</p><p>Post-LN 把 LN 放在加法之后，看似每层把尺度拉回，Xiong 等人指出初始化附近 LN 的雅可比会压残差通路，深层更依赖 warmup——那是稳定性单元的课。Pre-LN 让主干不经 LN，尺度漂移更直白，必须在 \\(F\\) 上动手。本课默认你已经选了某一种 LN 位置，只问：\\(F\\) 的起步该不该随 \\(L\\) 变。</p><p><span class="marginnote">「0.02 标准差」在 12 层 GPT-2 上暗含了某种深度折中。把同一常数贴到 80 层上，等于拒绝本课。深度变了，要么显式 \\(1/\\sqrt{L}\\)，要么走 μP / DeepNorm 的表，不能靠同一魔法数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三条常用处方，不要叠乘。</p><p><strong>残差输出缩放（GPT-2）。</strong> 每个子层最后的投影（注意力的 \\(W_O\\)、FFN 的输出矩阵）初始化方差再除 \\(N\\)，或等价地把该矩阵乘 \\(1/\\sqrt{N}\\)，其中 \\(N\\) 是残差层数。直觉：使 \\(\\sum_\\ell F_\\ell\\) 的起步方差对 \\(L\\) 不变。Radford 等人把它写进 GPT-2，作为「更深仍可训」的工程条款。</p><p><strong>T-Fixup（Huang 等, ICML 2020）。</strong> 对 Transformer 给出一组与层数相关的矩阵缩放，并在一定条件下去掉 LN 与 warmup。核心仍是：让残差分支在深度方向的 Lipschitz 与更新幅度受控。它假设特定的注意力与 FFN 结构；改 SwiGLU、改 RoPE 后系数要重验，不能当即插即用定理。</p><p><strong>DeepNorm（DeepNet, Wang 等）。</strong> 把 LN 的增益与残差系数写成 \\(\\alpha,\\beta\\) 随深度增长的函数，使极深（论文演示到上千层）仍有恒等路径。这是「初始化 + 结构系数」一起改，比只乘 \\(1/\\sqrt{L}\\) 更重。小模型上未必值得；要把层数加一个数量级时，才轮到它。</p><p>ReZero 把 \\(x\\leftarrow x+\\alpha F(x)\\) 的 \\(\\alpha\\) 起步设为 0，让网络从纯恒等长出来。与 \\(1/\\sqrt{L}\\) 同类，只是把深度因子交给一个可学习标量。LayerScale（Touvron 等）是对角版 \\(\\alpha\\)。本课把它们视为同一家族：残差增量必须先小。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>缩放作用在 \\(F\\) 的输出，不作用在 LN 之前的主干（Pre-LN 下主干是累加）。反向时 \\(dF\\) 也乘同一因子：深层起步不仅前向小，参数更新也小，避免第一步就离开可工作区。学习率 warmup 是另一条时间轴上的「先小」；深度缩放是结构轴上的「先小」。两条可以同时要，但不要用更长 warmup 去掩盖 \\(L\\) 倍方差错误——warmup 结束之后尺度问题还在。</p><p>与 <a href="/llm/mup">μP</a> 的关系：μP 管<strong>宽度</strong>极限下每层更新 \\(O(1)\\)；本课管<strong>深度</strong>上残差求和。Tensor Programs 对深度的保证弱于宽度，附录里的经验迁移不能当成与 fan-in 同级的定理。配方应分开写：宽度列一张表，深度列一个 \\(1/\\sqrt{L}\\) 或 DeepNorm 系数。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 LN 从配方里删掉。T-Fixup 的「去 LN」有结构前提，现代解码器几乎都保留 RMSNorm。也不处理嵌入表与 lm_head：它们不乘 \\(L\\) 次，下一课单独定标。MoE 的专家内部仍是残差块，专家数不是 \\(L\\)；不要把专家数填进 \\(1/\\sqrt{N}\\) 的 \\(N\\)。</p><p>深度缩放不能替代梯度裁剪，也不能替代后课的注意力 logit 控制。它只把「第一步的尺度」放回 \\(O(1)\\)。训练中途残差流再次涨起来，是激活漂移课的对象。</p>',21)),(r(),d(h,null,{default:t(()=>[m(o,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20X0%5B%22%E5%B5%8C%E5%85%A5%20x0%22%5D%20--%3E%20ADD%5B%22%E6%AE%8B%E5%B7%AE%E7%B4%AF%E5%8A%A0%20L%20%E6%AC%A1%22%5D%0A%20%20F%5B%22F%EF%BC%9AXavier%20%E5%B7%B2%E5%AE%88%E6%81%92%22%5D%20--%3E%20SCL%5B%22%E4%B9%98%201%2Fsqrt(L)%20%E6%88%96%20DeepNorm%22%5D%0A%20%20SCL%20--%3E%20ADD%0A%20%20ADD%20--%3E%20XL%5B%22x_L%20%E5%B0%BA%E5%BA%A6%E5%8F%97%E6%8E%A7%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e("h2",{id:"小结",tabindex:"-1"},[l("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[3]||(a[3]=e("ul",null,[e("li",null,"Xavier 守恒的是一层 \\(F\\)；残差把 \\(F\\) 加 \\(L\\) 次，必须再按深度缩小起步幅度。"),e("li",null,"GPT-2 的 \\(1/\\sqrt{N}\\)、T-Fixup、DeepNorm、ReZero / LayerScale 同属这一杠杆，不要叠乘。"),e("li",null,"深度因子与 μP 的宽度表、与 warmup 的时间表分工，不能互相冒充。"),e("li",null,"嵌入与输出头不是残差层，下一课另标。"),e("li",null,"出处：Radford et al., GPT-2, 2019；Huang et al., T-Fixup, ICML 2020；Wang et al., DeepNet, 2022。")],-1))])}const P=n(u,[["render",L]]);export{F as __pageData,P as default};
